sys_script_include.script:
var EventDataUtils = Class.create();
EventDataUtils.prototype = {
    initialize: function() {},
    fetchTasksForEvent: function(eventSysId) {
        var tasks = [];
        var gr = new GlideRecord('x_1790227_event_ma_event_task');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        while (gr.next()) {
            tasks.push({
                task_name: gr.getValue('u_task_name'),
                status: gr.getValue('u_status'),
                due_date: gr.getDisplayValue('u_due_date'),
                assigned_to: gr.getDisplayValue('assigned_to')
            });
        }
        gs.print('Tasks: ' + JSON.stringify(tasks));
        return tasks;
    },

    cancelOverdueTasks: function() {
        var now = new GlideDateTime();
        var gr = new GlideRecord('x_1790227_event_ma_event_task');
        gr.addQuery('u_due_date', '<', now);
        gr.addQuery('u_status', '!=', 'completed');
        gr.addQuery('u_status', '!=', 'cancelled');
        gr.query();
        while (gr.next()) {
            gr.u_status = 'cancelled';
            gr.update();
        }
        gs.print('Overdue tasks updated to Cancelled.');
    },

    fetchAttendeesForEvent: function(eventSysId) {
        var attendees = [];
        var gr = new GlideRecord('x_1790227_event_ma_attendee');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        while (gr.next()) {
            attendees.push({
                first_name: gr.getValue('u_first_name'),
                last_name: gr.getValue('u_last_name'),
                email: gr.getValue('u_email')
            });
        }
        gs.print('Attendees: ' + JSON.stringify(attendees));
        return attendees;
    },

    fetchVendorsForEvent: function(eventSysId) {
        var vendors = [];
        var gr = new GlideRecord('x_1790227_event_ma_vendor');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        while (gr.next()) {
            vendors.push({
                vendor_name: gr.getValue('u_vendor_name'),
                contact_person: gr.getValue('u_contact_person'),
                contact_number: gr.getValue('u_contact_number')
            });
        }
        gs.print('Vendors: ' + JSON.stringify(vendors));
        return vendors;
    },

    fetchBudgetForEvent: function(eventSysId) {
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        if (gr.next()) {
            var budgetDetails = {
                total_budget: gr.getValue('u_total_budget'),
                amount_spent: gr.getValue('u_amount_spent'),
                amount_remaining: gr.getValue('u_amount_remaining'),
                status: gr.getValue('u_status')
            };
            gs.print('Budget: ' + JSON.stringify(budgetDetails));
            return budgetDetails;
        }
        return {};
    },

    fetchFeedbackForEvent: function(eventSysId) {
        var feedbacks = [];
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        while (gr.next()) {
            feedbacks.push({
                rating: gr.getValue('u_rating'),
                comments: gr.getValue('u_comments')
            });
        }
        gs.print('Feedbacks: ' + JSON.stringify(feedbacks));
        return feedbacks;
    },

    fetchScheduleForEvent: function(eventSysId) {
        var schedules = [];
        var gr = new GlideRecord('x_1790227_event_ma_schedule');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        while (gr.next()) {
            schedules.push({
                activity_name: gr.getValue('u_activity_name'),
                start_time: gr.getDisplayValue('u_start_time'),
                end_time: gr.getDisplayValue('u_end_time'),
                status: gr.getValue('u_status')
            });
        }
        gs.print('Schedules: ' + JSON.stringify(schedules));
        return schedules;
    },

    fetchVenueForEvent: function(eventSysId) {
        var gr = new GlideRecord('x_1790227_event_ma_venue');
        gr.addQuery('u_event_id', eventSysId);
        gr.query();
        if (gr.next()) {
            var venueDetails = {
                venue_name: gr.getValue('u_venue_name'),
                location: gr.getValue('u_location'),
                capacity: gr.getValue('u_capacity'),
                contact_person: gr.getValue('u_contact_person'),
                contact_number: gr.getValue('u_contact_number')
            };
            gs.print('Venue: ' + JSON.stringify(venueDetails));
            return venueDetails;
        }
        return {};
    },

    type: 'EventDataUtils'
};
